25	func (d *DB) ApplyAuthenticationConfigMutation(ctx context.Context, mutation *store.AuthenticationConfigMutation) error {
26		tx, err := d.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
27		if err != nil {
28			return errors.Wrap(err, "failed to begin authentication configuration transaction")
29		}
30		defer func() {
