37			&general.Name, &general.Value, &general.Description,
38		)
39		if err == nil {
40			state.GeneralSetting = general
41		} else if !errors.Is(err, sql.ErrNoRows) {
42			return errors.Wrap(err, "failed to read GENERAL setting")
43		}
44		rows, err := tx.QueryContext(ctx, `SELECT id, uid FROM idp ORDER BY id`)
45		if err != nil {
46			return errors.Wrap(err, "failed to read identity providers")
47		}
48		defer rows.Close()
