52				rows.Close()
53				return errors.Wrap(err, "failed to scan identity provider")
54			}
55			state.IdentityProviders = append(state.IdentityProviders, provider)
56		}
57		if err := rows.Err(); err != nil {
58			rows.Close()
59			return errors.Wrap(err, "failed to iterate identity providers")
60		}
61		if err := rows.Close(); err != nil {
62			return errors.Wrap(err, "failed to close identity provider rows")
63		}
