15	// Build setting name from key
16	const buildInstanceSettingName = (key: InstanceSetting_Key): string => {
17	  const keyName = InstanceSetting_Key[key];
18	  return `instance/settings/${keyName}`;
19	};
20	
21	// Hook to fetch instance resource statistics. Admin only on the server side.
22	export function useInstanceStats() {
23	  return useQuery({
24	    queryKey: instanceKeys.stats(),
25	    queryFn: () => instanceServiceClient.getInstanceStats({}),
26	    staleTime: 60_000, // 60s — matches server-side cache TTL
27	  });
28	}
