30	// Hook to fetch instance profile
31	export function useInstanceProfile() {
32	  return useQuery({
33	    queryKey: instanceKeys.profile(),
34	    queryFn: async () => {
35	      const profile = await instanceServiceClient.getInstanceProfile({});
36	      return profile;
37	    },
38	    staleTime: 1000 * 60 * 10, // 10 minutes - instance profile rarely changes
39	  });
40	}
