42	// Hook to fetch a specific instance setting
43	export function useInstanceSetting(key: InstanceSetting_Key) {
44	  return useQuery({
45	    queryKey: instanceKeys.setting(key),
46	    queryFn: async () => {
47	      const setting = await instanceServiceClient.getInstanceSetting({
48	        name: buildInstanceSettingName(key),
49	      });
50	      return setting;
51	    },
52	    staleTime: 1000 * 60 * 5, // 5 minutes
53	  });
54	}
55	
56	// Hook to fetch multiple instance settings
57	export function useInstanceSettings(keys: InstanceSetting_Key[]) {
58	  return useQuery({
59	    queryKey: instanceKeys.settingsBatch(keys),
60	    queryFn: async () => {
61	      const response = await instanceServiceClient.batchGetInstanceSettings({
62	        names: keys.map(buildInstanceSettingName),
63	      });
64	      return response.settings;
65	    },
66	    staleTime: 1000 * 60 * 5, // 5 minutes
67	  });
68	}
