70	// Hook to update instance setting
71	export function useUpdateInstanceSetting() {
72	  const queryClient = useQueryClient();
73	
74	  return useMutation({
75	    mutationFn: async (setting: InstanceSetting) => {
76	      await instanceServiceClient.updateInstanceSetting({ setting });
77	      return setting;
78	    },
79	    onSuccess: (setting) => {
80	      // Extract key from setting name and invalidate
81	      const keyMatch = setting.name.match(/instance\/settings\/(\w+)/);
82	      if (keyMatch) {
83	        const keyName = keyMatch[1] as keyof typeof InstanceSetting_Key;
84	        const key = InstanceSetting_Key[keyName];
85	        if (key !== undefined) {
